// Delivery 4 database layer — golden reads. An in-memory PGlite migrated from ./drizzle and seeded from the prototype;
// the DAL output is compared with the prototype's own render values (delivery4.golden.json, generated by
// scripts/proto-golden-d4.ts: the prototype logic evaluated in node:vm, default state, EN) for the Project BOM (flat,
// tree, where-used, compare, PU/PR), PLM and the part record, ECOs (through the Vigie mirror), Drawings, Purchase
// orders, Deliveries, Stock, Sourcing and the supply-chain kinds of My approvals. The screen-side formatting is redone
// here with the prototype's rules to show the data is complete. Deliberate deviations are asserted explicitly
// (BOM value without double count, PU/PR stock, projects without data, zero-padded prototype dates).
import { beforeAll, describe, expect, it } from 'vitest';
import { money, moneyEur } from '@/lib/format';
import { setDb } from '@/server/db/client';
import { ECO_APPROVER_KEYS, fmtDOfIso, matchState, stockSource } from '@/server/db/codes';
import { openDatabase } from '@/server/db/open';
import { PROTO } from '@/server/prototype';
import {
  getProjectAssembly, getProjectBom, getRevisionComparison, getSpareList, getWhereUsed, resolveWhereUsedQuery, type BomTreeNode,
} from './bom';
import { listReceipts, qcQueue, receiptsQcPendingByProject } from './deliveries';
import { getDrawing, getVaultSyncState, listDrawings } from './drawings';
import { countEcosInApproval, ecoApprovalQueue, getEco, installedBasePins, listEcos, openEcoByPart, pinSummary } from './eco';
import { machinesCarryingPart } from './machines';
import { getPartRecord, listParts } from './parts';
import {
  canAwardRfqs, countInvoicesToResolve, countOrdersToReceive, getBomShortfall, invoiceQueue, listPurchaseOrders, listRfqs, listSupplierInvoices, poApprovalQueue,
  posAwaitingApprovalByProject, rfqAwardQueue,
} from './purchasing';
import { countStockBelowMin, getStockPosition, getX3StockSync, listStock, listStockMovements } from './stock';
import { getSupplierScorecard, listStorageLocations } from './suppliers';
import golden from './delivery4.golden.json';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = golden as any;
const $ = (v: number) => moneyEur(v, 'en');
const f = (k: number) => money(k, 'en');
const n = (v: number) => v.toLocaleString('en-US');
/** Prototype dates are partly zero-padded ("04 May"); the rebuild formats every date the same way ("4 May"). */
const day = (s: string) => s.replace(/(^|· )0(\d)/g, '$1$2');
const DATA = ['HLT-026', 'NDC-031', 'RCF-019', 'ERP-202', 'WSA-044', 'MSR-012'];
const PERSONA: Record<string, string> = Object.fromEntries((PROTO.PERSONAS ? Object.entries(PROTO.PERSONAS as Record<string, [string, string]>) : []).map(([r, [name]]) => [r, name]));
const kv = (ks: any[]) => ks.map((k: any) => [k.value, k.sub]);
/** Copy without some keys (fields the DAL leaves to the screen or that differ on purpose). */
const omit = (o: Record<string, unknown>, keys: string[]) => Object.fromEntries(Object.entries(o).filter(([k]) => !keys.includes(k)));
/**
 * The prototype stripped the actual-date marker with `.replace(' A', '')`, which also cut the month of an activity
 * starting in Aug or Apr ("Needed from 14ug A"); the rebuild only removes a trailing " A" (deliberate fix).
 */
const ACTUAL_STRIP_FIX: Record<string, string> = { 'Needed from 14ug A': 'Needed from 14 Aug', 'Needed from 15pr ’27': 'Needed from 15 Apr ’27' };

beforeAll(async () => {
  setDb(await openDatabase());
}, 60_000);

// ── Project BOM ────────────────────────────────────────────────────────────────────────────────────────

describe('project BOM (09 §1)', () => {
  it.each(DATA)('%s: flat list and KPI inputs reproduce bomRows / bomKpis', async (code) => {
    const bom = (await getProjectBom(code))!;
    const g = G.bom[code];
    const ecos = await openEcoByPart();
    const rows = [...bom.lines].sort((a, b) => a.ref.localeCompare(b.ref)).map((l) => ({
      // E-2a (R-103): the unit price is the ordered price, else the last purchase price, else the catalogue price.
      ref: l.ref, qty: n(l.quantity), total: $(l.totalEur), price: $(l.unitPriceEur), status: l.statusLabel, eco: ecos[l.ref] ?? '', used: l.alsoUsedIn.join(', ') || '—',
      usedCount: l.usage.length ? `${l.usage.length} ${l.usage.length === 1 ? 'project' : 'projects'}` : '—', restr: l.exportRestriction ?? '—',
      lead: l.leadWeeks ? `${l.leadWeeks} wks` : '—', pu: l.wearSpare ?? '—', mfr: l.manufacturer,
    }));
    expect(rows).toEqual(g.rows);
    const s = bom.summary;
    // The prototype's BOM value adds every line (09 OQ6), here at the E-2a prices (golden generated with scripts/proto-e2a.ts).
    const protoValue = bom.lines.reduce((a, l) => a + l.totalEur, 0);
    expect([[s.articles, `${n(s.units)} units in total`], [f(protoValue / 1000), 'Ordered, else last purchase, else catalogue price'], [s.notValidated, 'Blocked for purchasing'],
      [s.outdatedOrObsolete, 'Replace before ordering'], [s.exportRestricted, 'Lines needing customs review']]).toEqual(kv(g.kpis));
    expect(bom.hasTree).toBe(g.hasTree);
  });

  it('BOM value counts each article once (09 OQ6): HLT-026 €14.05M in the prototype, assemblies valued through their components', async () => {
    const bom = (await getProjectBom('HLT-026'))!;
    expect(bom.lines.filter((l) => l.valuedByComponents).map((l) => l.ref)).toEqual(['ASM-RMG-250', 'ASM-STR-100', 'ASM-GIR-200', 'ASM-BOG-300', 'ASM-HST-400', 'ASM-ELE-600', 'ASM-DRV-700', 'ASM-CTL-800']);
    expect(f(bom.summary.listValueEur / 1000)).toBe('€14.05M');
    expect(bom.summary.valueEur).toBe(bom.lines.filter((l) => !l.valuedByComponents).reduce((s, l) => s + l.totalEur, 0));
    expect(bom.summary.valueEur).toBeLessThan(bom.summary.listValueEur);
  });

  it('projects without data have an empty BOM (no Harbor Line fallback)', async () => {
    const bom = (await getProjectBom('EWA-051'))!;
    expect([bom.lines.length, bom.hasTree, await getProjectAssembly('EWA-051'), await getSpareList('EWA-051')]).toEqual([0, false, null, null]);
    expect(G.bom['EWA-051'].kpis[0].value).toBe(35); // the prototype showed Harbor Line's
  });

  it('assembly tree of HLT-026 reproduces treeRows (roll-up at the E-2a price, R-103)', async () => {
    const asm = (await getProjectAssembly('HLT-026'))!;
    expect(asm.rows.map((r) => ({ ref: r.ref, qty: r.qty, ext: n(r.extended), unit: $(r.unitCostEur), total: $(r.extendedCostEur), rev: r.revision ?? '—', status: r.statusLabel, pad: `${r.depth * 18 + 6}px`, has: r.children.length > 0 })))
      .toEqual(G.tree);
  });

  it('node drawers: identification, costed roll-up, used-in paths (nodeVals)', async () => {
    const asm = (await getProjectAssembly('HLT-026'))!;
    const perProject = (r: BomTreeNode) => {
      // Π q along the first path from the root, the node included.
      const chain = [...r.path.map((p) => asm.rows.find((x) => x.ref === p)!), r];
      return chain.reduce((a, x) => a * x.qty, 1);
    };
    for (const r of asm.rows) {
      const g = G.nodes[r.ref];
      const has = r.children.length > 0;
      expect(g.ident.map((x: any) => x.v)).toEqual([r.revision ?? '—', r.makeBuyLabel, r.manufacturer, r.manufacturerRef, r.leadWeeks ? `${r.leadWeeks} weeks` : '—', has ? `${r.leafCount} parts · ${r.children.length} direct children` : 'Leaf part']);
      const d = r.unitCostEur - r.listPriceEur;
      // E-2a (R-103): "Rolled-up cost" and its price basis (ordered, last purchase, catalogue; roll-up for an assembly).
      const basis = { ordered: 'Ordered price', last_purchase: 'Last purchase price', catalogue: 'Catalogue price', rollup: 'Roll-up of components' }[r.priceSource];
      expect(g.cost.map((x: any) => [x.k, x.v])).toEqual([
        ['Rolled-up cost', $(r.unitCostEur)], ['Price basis', basis], ['List / standard price', $(r.listPriceEur)], ['Delta', (d >= 0 ? '+' : '−') + $(Math.abs(d))],
        [`Per project (× ${perProject(r)})`, $(r.unitCostEur * perProject(r))],
      ]);
      expect(g.parents).toEqual([r.path.join(' › ') || 'Top level']);
    }
  });

  it('where-used reproduces usedVals (default CR-BRG-SKF; paths, projects, purchase orders)', async () => {
    for (const [q, g] of Object.entries(G.used as Record<string, any>)) {
      const ref = await resolveWhereUsedQuery(q === '(default)' ? '' : q);
      const w = (await getWhereUsed(ref, 'HLT-026'))!;
      expect(w.part.ref).toBe(g.ref);
      expect(w.paths.map((p) => ({ chain: p.chain.map((c) => `${c.ref} ×${c.qty}`).join('  ›  '), qty: `${n(p.perProject)} per project`, leaf: ref }))).toEqual(g.rows);
      expect(w.projects.map((p) => ({ name: p.name, qty: `${n(p.quantity)} units`, status: p.stageLabel }))).toEqual(g.projects.map((p: any) => ({ name: p.name, qty: p.qty, status: p.status })));
      expect(w.purchaseOrders.map((o) => ({ id: o.number, project: o.projectCode, supplier: o.supplier, status: o.statusLabel }))).toEqual(g.pos);
      expect(w.part.equivalents.join(', ') || '—').toBe(g.equiv);
    }
  });

  it('compare revisions reproduces cmpVals (+€19,180 per crane)', async () => {
    const c = (await getRevisionComparison('HLT-026'))!;
    const g = G.compare;
    expect(`${c.assemblyRef} · rev ${c.fromRevision} → rev ${c.toRevision}`).toBe(g.title);
    expect(`${new Date(c.date + 'T00:00:00Z').getUTCDate()} Sep 2026 · ${c.ecoNumber}`).toBe(g.sub);
    expect(c.lines.map((l) => ({ line: l.path, name: l.name, a: l.qtyFrom == null ? '—' : String(l.qtyFrom), b: l.qtyTo == null ? '—' : String(l.qtyTo), kind: l.kindLabel, delta: l.deltaEur ? (l.deltaEur > 0 ? '+' : '−') + $(Math.abs(l.deltaEur)) : '—' })))
      .toEqual(g.rows.map((r: any) => ({ line: r.line, name: r.name, a: r.a, b: r.b, kind: r.kind, delta: r.delta })));
    expect(`${c.totalDeltaEur >= 0 ? '+' : '−'}${$(Math.abs(c.totalDeltaEur))} per crane`).toBe(g.total);
  });

  it('PU/PR lists reproduce spareRows / spKpis; stock is the real on-hand (the prototype always showed none, 00 §7.16)', async () => {
    const sl0 = (await getSpareList('HLT-026'))!;
    expect(sl0.systems.map((s) => (s.isRoot ? 'Complete system' : s.name))).toEqual(G.spSeg);
    for (const [sys, g] of Object.entries(G.spares as Record<string, any>)) {
      const sl = (await getSpareList('HLT-026', sys))!;
      expect(sl.systemName).toBe(g.sysName);
      expect(sl.rows.map((r) => ({
        ref: r.ref, kind: r.kind, qPer: r.qtyPerSystem, qTotal: r.recommendedQty, note: r.note ?? '—', price: $(r.lastPriceEur), total: $(r.totalEur), lead: r.leadWeeks ? `${r.leadWeeks} wks` : '—',
        frozen: r.underChange, pinned: r.pins.length > 0,
        pinnedText: r.pinSummary ? `Keep for the installed base · ${r.pinSummary.machines} ${r.pinSummary.machines === 1 ? 'machine' : 'machines'} · ${r.pinSummary.ecos.join(', ')}` : '',
      }))).toEqual(g.rows.map((r: any) => omit(r, ['stock', 'stockText'])));
      const value = sl.rows.reduce((a, r) => a + r.totalEur, 0);
      expect([[sl.rows.length, `${sl.rows.filter((r) => r.kind === 'PU').length} wear · ${sl.rows.filter((r) => r.kind === 'PR').length} spare`],
        [f(value / 1000), `At last purchase price · × ${sl.systemQty} ${sl.systemQty > 1 ? 'systems' : 'system'}`],
        [sl.rows.filter((r) => (r.leadWeeks ?? 0) > 8).length, 'Order with the main equipment'], [sl.rows.filter((r) => r.underChange).length, 'Frozen by an open ECO']])
        .toEqual([g.kpis[0], g.kpis[1], g.kpis[3], g.kpis[4]].map((k: any) => [k.value, k.sub]));
      expect(g.rows.every((r: any) => r.stockText === 'None in stock')).toBe(true);
    }
    const all = (await getSpareList('HLT-026'))!;
    expect(all.rows.filter((r) => r.inStock > 0).map((r) => [r.ref, r.inStock])).toEqual([['CR-BRG-SKF', 16], ['HST-ROP-28', 2], ['FD-DET-OPT2', 60]]);
    expect(all.rows.filter((r) => r.inStock < r.recommendedQty).length).toBe(10); // "Not in stock": 10 of 12 (the prototype: 12)
  });
});

// ── PLM and the part record ────────────────────────────────────────────────────────────────────────────

describe('PLM catalogue and part record (09 §2–3)', () => {
  it('catalogue rows and KPI inputs reproduce plmRows / plmKpis', async () => {
    const all = await listParts();
    const ecos = await openEcoByPart();
    expect([...all].sort((a, b) => a.ref.localeCompare(b.ref)).map((p) => ({
      ref: p.ref, name: p.name, type: p.typeLabel, mb: p.makeBuyLabel, pu: p.wearSpare ?? '—', mfr: p.manufacturer, mfrRef: p.manufacturerRef ?? '', price: $(p.listPriceEur),
      lead: p.leadWeeks ? `${p.leadWeeks} wks` : '—', status: p.statusLabel, eco: ecos[p.ref] ?? '', restr: p.exportRestriction ?? '—',
      usedCount: p.usage.length ? `${p.usage.length} ${p.usage.length === 1 ? 'project' : 'projects'}` : '—',
    }))).toEqual(G.plm.rows);
    const bad = all.filter((p) => (p.status === 'outdated' || p.status === 'obsolete') && p.usage.length);
    const lead = all.filter((p) => p.leadWeeks);
    expect([
      [all.length, `${all.filter((p) => p.makeBuy === 'manufactured').length} manufactured · ${all.filter((p) => p.makeBuy === 'purchased').length} purchased`],
      [`${Math.round((all.filter((p) => p.status === 'validated').length / all.length) * 100)}%`, `${all.filter((p) => p.status === 'not_validated').length} awaiting qualification`],
      [bad.length, bad.map((p) => p.ref).join(' · ') || 'None'], [all.filter((p) => p.exportRestriction).length, 'Licence or notification needed'],
      [`${Math.round(lead.reduce((a, p) => a + p.leadWeeks!, 0) / lead.length)} wks`, 'Purchased & manufactured'],
    ]).toEqual(kv(G.plm.kpis));
  });

  it('every part record reproduces partVals (identification, commercial & export, equivalents, spare list, projects, ECOs, installed base)', async () => {
    for (const [ref, g] of Object.entries(G.parts as Record<string, any>)) {
      const p = (await getPartRecord(ref))!;
      expect(p.statusNote ?? '').toBe(g.warn);
      expect(g.ident.map((x: any) => x.v)).toEqual([p.makeBuyLabel, p.wearSpareLabel ?? '—', p.typeLabel, p.manufacturer, p.manufacturerRef ?? '', p.revision ?? '—', p.leadWeeks ? `${p.leadWeeks} weeks` : '—']);
      expect(g.comm.map((x: any) => x.v)).toEqual([$(p.listPriceEur), p.hsCode ?? 'n/a', p.exportRestriction ?? 'None',
        `${n(p.totalQuantity)} units · ${p.usage.length} ${p.usage.length === 1 ? 'project' : 'projects'}`, $(p.committedValueEur)]);
      expect(p.equivalentParts.map((e) => ({ ref: e.ref, name: e.name, status: e.statusLabel }))).toEqual(g.equiv);
      expect(p.spareList.map((s) => ({ ref: s.ref, name: s.name, kind: s.kind, qty: s.qtyPerSystem }))).toEqual(g.spares);
      expect(p.projects.map((x) => ({ code: x.shortCode, name: x.name, qty: `${n(x.quantity)} units`, status: x.stageLabel }))).toEqual(g.projects);
      const ecos = (await listEcos({ partRefs: [ref] })).filter((e) => e.status !== 'rejected');
      expect(ecos.map((e) => ({ id: e.number, title: e.title, status: e.statusLabel }))).toEqual(g.ecoList);
      expect((await machinesCarryingPart(ref)).map((m) => ({ id: m.id, name: m.name, gen: m.generation, revText: `rev ${m.revision}`, state: m.stateLabel, eco: m.ecoNumber ?? '' }))).toEqual(g.fleetUse);
    }
  });
});

// ── ECOs (Vigie mirror) ────────────────────────────────────────────────────────────────────────────────

describe('ECOs read through the Vigie connector (mock over the seeded mirror)', () => {
  it('rows reproduce ecoRows (status as Vigie reports it, pending dispositions, lock)', async () => {
    const ecos = await listEcos();
    expect(ecos.map((e) => ({
      id: e.number, title: e.title, type: e.typeLabel, status: e.statusLabel, parts: e.parts.slice(0, 2).join(', ') + (e.parts.length > 2 ? ` +${e.parts.length - 2}` : ''),
      projects: e.projectNames.join(', '), by: e.requestedBy, date: day(fmtDOfIso(e.raisedOn)), cost: e.costEur ? `+${$(e.costEur)}` : '—',
      sched: e.scheduleDays ? `${e.scheduleDays > 0 ? '+' : ''}${e.scheduleDays} d` : '—', hasPend: e.pendingDispositions > 0 && !['draft', 'rejected', 'released'].includes(e.status),
      pendText: `${e.pendingDispositions} ${e.pendingDispositions === 1 ? 'disposition pending' : 'dispositions pending'}`, lockIcon: e.locked ? 'ph ph-lock-simple' : 'ph ph-hourglass',
      canStart: e.status === 'draft', canSubmit: e.status === 'impact_analysis' && e.interchangeability !== null, needInterch: e.status === 'impact_analysis' && e.interchangeability === null,
    }))).toEqual(G.eco.rows.map((r: any) => ({ ...omit(r, ['approvals']), date: day(r.date) })));
    expect(ecos.map((e) => e.approvalsView.map((a) => a.decision))).toEqual(G.eco.rows.map((r: any) => r.approvals.map((d: string) => (d === 'var(--color-accent)' ? 'ok' : d === 'var(--color-neutral-100)' ? 'rejected' : 'pending'))));
    expect(ecos.every((e) => e.vigieUrl === `http://localhost:3200/modifications-techniques/${e.number}`)).toBe(true);
  });

  it.each(['director', 'pm', 'englead', 'quality', 'procurement', 'client'])('KPI inputs for %s reproduce ecoKpis', async (role) => {
    const ecos = await listEcos();
    const open = ecos.filter((e) => e.open);
    const key = role === 'englead' || role === 'quality' || role === 'pm' ? role : null;
    const released = ecos.filter((e) => e.status === 'released');
    const locked = ecos.filter((e) => e.locked).length;
    expect([
      [open.length, `${ecos.length} in total`],
      [key ? (await ecoApprovalQueue({ name: PERSONA[role], role })).length : 0, key ? `As ${(PROTO.PERSONAS as Record<string, [string, string]>)[role][1]}` : 'Switch to an approver role'],
      [released.length, `Cost impact ${$(released.reduce((a, e) => a + e.costEur, 0))}`],
      [new Set(open.flatMap((e) => e.projects)).size, 'By open changes'], [new Set(open.flatMap((e) => e.parts)).size, 'Frozen for new orders'],
      [open.reduce((a, e) => a + e.pendingDispositions, 0), locked ? `${locked} ${locked === 1 ? 'release blocked' : 'releases blocked'}` : 'No release blocked'],
    ]).toEqual(kv(G.eco.byRole[role].kpis));
    expect(await countEcosInApproval()).toBe(1);
  });

  it('drawers reproduce ecoVals (impact analysis, approvers, effectivity, pinned list)', async () => {
    for (const [id, g] of Object.entries(G.eco.drawers as Record<string, any>)) {
      const e = (await getEco(id))!;
      expect(`${e.requestedBy} · ${fmtDOfIso(e.raisedOn)}`).toBe(day(g.by));
      expect(`${e.parts[0]} · ${e.fromRevision} → ${e.toRevision}`).toBe(g.revText);
      expect(e.interchangeabilityLabel).toBe(g.interchLabel);
      expect(e.pendingDispositions ? `${e.pendingDispositions} ${e.pendingDispositions === 1 ? 'disposition pending' : 'dispositions pending'}` : 'All dispositions set').toBe(g.pendText);
      expect(e.locked).toBe(g.isLocked);
      expect(g.impact.map((x: any) => [x.k, x.v])).toEqual([
        ['Projects & BOMs', e.projectNames.join(', ')], ['Open purchase orders', e.openPurchaseOrders.map((o) => `${o.number} · ${o.supplier} · ${o.statusLabel}`).join(' · ') || 'None'],
        ['Stock to scrap / rework', e.stockImpact], ['Cost delta', e.costEur ? `+${$(e.costEur)}` : 'None'],
        ['Schedule delta', e.scheduleDays ? `${e.scheduleDays > 0 ? '+' : ''}${e.scheduleDays} days` : 'None'], ['Documents to update', e.documentRefs.join(' · ')],
      ]);
      expect(e.approvalsView.map((a) => ({ label: a.label, who: a.approver, state: a.decisionLabel }))).toEqual(g.approvers.map((a: any) => ({ label: a.label, who: a.who, state: a.state })));
      const projs = e.effectivityView.filter((t) => t.targetType === 'project');
      const mchs = e.effectivityView.filter((t) => t.targetType === 'machine');
      expect([projs.length, mchs.length]).toEqual([g.projCount, g.mchCount]);
      expect(projs.map((t) => ({ name: t.label, sub: t.targetRef, label: t.dispositionLabel ?? 'Pending', note: t.note ?? (t.isAutomatic ? 'Design phase — updated automatically' : '') })))
        .toEqual(g.dispProjects.map((t: any) => ({ name: t.name, sub: t.sub, label: t.label, note: t.note })));
      expect(mchs.map((t) => ({ name: t.label, revText: `${t.fittedPartRef} rev ${t.fittedRevision}`, label: t.dispositionLabel ?? 'Pending', note: t.note ?? (t.isAutomatic ? 'Not interchangeable — pinned automatically' : '') })))
        .toEqual(g.dispMachines.map((t: any) => ({ name: t.name, revText: t.revText, label: t.label, note: t.note })));
      expect(mchs.filter((t) => t.disposition === 'pinned').map((t) => `${t.targetRef} (${t.fittedPartRef} rev ${t.fittedRevision})`).join(' · ')).toBe(g.pinnedList);
      expect(e.stepIndex).toBe(['Draft', 'Impact analysis', 'In approval', 'Released'].indexOf(e.statusLabel));
    }
  });

  it('installed-base pins reproduce pinnedFor on the stock lines (FD-DET-OPT, FD-DET-OPT2 via ECO-2026-015 / MCH-029)', async () => {
    const pins = await installedBasePins();
    const text = (ref: string) => {
      const ps = pinSummary(pins[ref]);
      return ps ? `Keep for the installed base · ${ps.machines} ${ps.machines === 1 ? 'machine' : 'machines'} · ${ps.ecos.join(', ')}` : '';
    };
    for (const r of G.stock.rows) expect(text(r.ref)).toBe(r.pinnedText);
    expect(text('FD-DET-OPT')).toBe('Keep for the installed base · 1 machine · ECO-2026-015');
  });
});

// ── Drawings ───────────────────────────────────────────────────────────────────────────────────────────

describe('drawings — PDM vault mirror (09 §5)', () => {
  it('register, KPI inputs and revision history reproduce dwgRows / dwgKpis / dwgVals', async () => {
    const rows = await listDrawings();
    expect(rows.map((d) => ({ no: d.number, title: d.title, part: d.partRef, partName: d.partName, rev: d.revision, state: d.stateLabel, path: d.vaultPath, by: d.checkedInBy, date: day(fmtDOfIso(d.checkedInOn)), eco: d.ecoNumber ?? '—' })))
      .toEqual(G.drawings.rows.map((r: any) => ({ ...r, date: day(r.date) })));
    const s = (await getVaultSyncState())!;
    expect([[s.drawingsInVault.toLocaleString('fr-FR').replace(/ /g, ' '), `${s.linkedDrawings} linked to catalogue parts`], [rows.filter((d) => d.state === 'released').length, 'Current revision'],
      [rows.filter((d) => d.state === 'wip' || d.state === 'under_review').length, 'Linked to open ECOs'], [rows.filter((d) => d.state === 'obsolete').length, 'Superseded by rev 2'], [s.time, 'SolidWorks PDM · today · read-only']])
      .toEqual(kv(G.drawings.kpis));
    for (const d of rows) {
      const x = (await getDrawing(d.number))!;
      const g = G.drawings.drawers[d.number];
      expect(x.revisions.map((r, i) => ({ rev: r.revision, label: i === 0 ? `Current · ${day(fmtDOfIso(r.checkedInOn!))}` : 'Superseded', eco: i === 0 ? r.ecoNumber ?? '—' : '—' })))
        .toEqual(g.hist.map((h: any) => ({ ...h, label: day(h.label) })));
      expect(g.meta.map((m: any) => m.v)).toEqual([`${x.partRef}${x.partName ? ' · ' + x.partName : ''}`, x.vaultFile, `${x.checkedInBy} · ${g.meta[2].v.split(' · ')[1]}`, x.ecoNumber ?? 'None', x.formats, x.partStatusLabel ?? '—']);
    }
  });
});

// ── Purchase orders ────────────────────────────────────────────────────────────────────────────────────

describe('purchase orders (08 §2)', () => {
  it.each([...DATA, 'EWA-051'])('%s: rows, KPI inputs and shortfall reproduce poRows / poKpis / shortfall', async (code) => {
    const pos = await listPurchaseOrders(code);
    const g = G.orders[code];
    if (code === 'EWA-051') {
      expect(pos).toEqual([]); // the prototype showed Harbor Line's orders
      return;
    }
    expect(pos.map((o) => ({
      id: o.number, supplier: o.supplier, lineSummary: o.lines.map((l) => l.ref).slice(0, 2).join(', ') + (o.lines.length > 2 ? ` +${o.lines.length - 2}` : ''),
      lineCount: `${o.lines.length} ${o.lines.length === 1 ? 'line' : 'lines'} · ${n(o.orderedUnits)} units${o.partStatusIssue ? ' · part status issue' : ''}`,
      value: f(o.valueEur / 1000), status: o.statusLabel, ordered: o.status === 'draft' ? '—' : day(fmtDOfIso(o.orderedOn!)),
      expected: o.status === 'received' ? 'Delivered' : o.expectedOn ? day(fmtDOfIso(o.expectedOn)) : 'To confirm', need: o.neededFor ? `${o.neededFor.code} · ${o.neededFor.name}` : '—',
      risk: o.late ? 'Activity already started — delivery is late' : o.neededFor?.startText ? `Needed from ${o.neededFor.startText}` : '', canSubmit: o.status === 'draft', canApprove: o.status === 'awaiting_approval',
    }))).toEqual(g.rows.map((r: any) => ({ ...r, ordered: day(r.ordered), expected: day(r.expected), risk: ACTUAL_STRIP_FIX[r.risk] ?? r.risk })));
    const committed = pos.filter((o) => o.status !== 'cancelled' && o.status !== 'draft').reduce((a, o) => a + o.valueEur, 0);
    expect([[pos.filter((o) => !['received', 'cancelled'].includes(o.status)).length, `${pos.length} orders in total`], [f(committed / 1000), 'Ordered, not cancelled'],
      [pos.filter((o) => o.late).length, 'See Deliveries for goods receipt'], [pos.filter((o) => o.status === 'awaiting_approval').length, 'Blocks ordering']]).toEqual(kv(g.kpis));
    const sf = await getBomShortfall(code);
    expect(sf.lines.map((l) => [l.ref, n(l.need), l.need])).toEqual(g.shortfall);
    expect(`${sf.lines.length} ${sf.lines.length === 1 ? 'BOM article is' : 'BOM articles are'} not fully ordered`).toBe(g.shortfallTitle);
    expect(`${f(sf.valueEur / 1000)} still to commit at list price`).toBe(g.shortfallSub);
    for (const o of pos) {
      const d = g.drawers[o.number];
      expect(o.lines.map((l) => ({ ref: l.ref, name: l.name, qty: n(l.orderedQty), recv: n(l.receivedQty), price: $(l.unitPriceEur), total: $(l.totalEur), pstatus: l.partStatusLabel }))).toEqual(d.lines);
      expect(d.meta.map((m: any) => m.v)).toEqual([f(o.valueEur / 1000), o.status === 'draft' ? 'Not yet' : d.meta[1].v, d.meta[2].v, o.neededFor ? `${o.neededFor.code} · ${o.neededFor.name}` : '—', o.deliveryTerms]);
      expect(day(d.meta[1].v)).toBe(o.status === 'draft' ? 'Not yet' : day(fmtDOfIso(o.orderedOn!)));
    }
    const bad = pos.flatMap((o) => o.lines.filter((l) => l.partStatus !== 'validated').map((l) => ({ o: o.number, w: `${l.ref} is ${l.partStatusLabel.toLowerCase()}` })));
    for (const o of pos) expect(g.drawers[o.number].warn).toBe(bad.filter((b) => b.o === o.number).length ? bad.filter((b) => b.o === o.number).map((b) => b.w).join(' · ') + ' — resolve in PLM before this order is released.' : '');
  });

  it('sidebar badge: orders awaiting approval per project', async () => {
    expect(await posAwaitingApprovalByProject()).toEqual({ 'HLT-026': 1, 'WSA-044': 1 });
  });
});

