describe('stock & storages (08 §4)', () => {
  it('rows, KPI inputs, movements and drawers reproduce stockRows / stockKpis / moveRows / stockSel', async () => {
    const rows = await listStock();
    const locs = await listStorageLocations();
    const pins = await installedBasePins();
    expect(rows.map((r) => {
      const ps = pinSummary(pins[r.ref]);
      return {
        ref: r.ref, name: r.name, loc: r.location, locType: r.locationTypeLabel, onHand: n(r.onHand), reserved: r.reserved ? `${n(r.reserved)}${r.reservedForShort ? ' · ' + r.reservedForShort : ''}` : '—',
        avail: n(r.available), min: r.minQty ? String(r.minQty) : '—', below: r.belowMin ? true : (r.minQty ? false : 0), value: $(r.valueEur), source: r.sourceLabel, last: day(fmtDOfIso(r.lastMovementOn)),
        pinned: !!ps, pinnedText: ps ? `Keep for the installed base · ${ps.machines} ${ps.machines === 1 ? 'machine' : 'machines'} · ${ps.ecos.join(', ')}` : '',
      };
    })).toEqual(G.stock.rows.map((r: any) => ({ ...r, last: day(r.last) })));
    const sync = (await getX3StockSync())!;
    const value = rows.reduce((a, r) => a + r.valueEur, 0);
    expect([[f(value / 1000), `${rows.length} lines · ${locs.length} locations`], [rows.filter((r) => r.belowMin).length, 'Reorder or transfer'],
      [rows.filter((r) => r.locationType === 'quarantine').reduce((a, r) => a + r.onHand, 0), 'Awaiting quality decision'], [sync.time, `Today · ${sync.x3Lines} lines from Sage X3`],
      [sync.localLines, 'To push back to X3']]).toEqual(kv(G.stock.kpis));
    expect(locs.map((l) => [l.name, rows.filter((r) => r.location === l.name).length])).toEqual(G.stock.chips.slice(1));
    expect((await listStockMovements({ limit: 8 })).map((m) => ({ when: m.when, type: m.typeLabel, ref: m.ref, qty: m.qty, where: m.where, who: m.who }))).toEqual(G.stock.moves);
    for (const [i, r] of rows.entries()) {
      const d = (await getStockPosition(r.id))!;
      const g = G.stock.drawers[String(i)];
      expect(g.meta.map((m: any) => m.v)).toEqual([n(d.onHand), d.reserved ? `${d.reserved}${d.reservedForShort ? ' · ' + d.reservedForShort : ''}` : '—', n(d.available), d.minQty || '—', $(d.unitCostEur), g.meta[5].v]);
      expect(day(g.meta[5].v)).toBe(day(fmtDOfIso(d.lastMovementOn)));
      expect(d.movements.map((m) => ({ when: m.when, type: m.typeLabel, qty: m.qty, where: m.where, who: m.who }))).toEqual(g.moves);
      expect(d.transferTargets.map((t) => t.shortLabel)).toEqual(g.targets);
    }
    expect(await countStockBelowMin()).toBe(1);
    expect(rows.filter((r) => r.source === 'local').map((r) => stockSource.label(r.source))).toEqual(['Local', 'Local', 'Local']);
  });
});

