describe('sourcing — RFQs, invoices 3-way match, suppliers (08 §1)', () => {
  it('RFQ rows, KPI inputs and drawers (per role) reproduce rfqRows / rfqKpis / rfqVals', async () => {
    const rfqs = await listRfqs();
    expect(rfqs.map((r) => ({
      id: r.number, title: r.title, part: r.partRef, qty: r.quantity, due: day(fmtDOfIso(r.replyDueOn)), owner: r.owner,
      quotesText: r.quotes.length ? `${r.quotes.length} quotes · from ${$(r.bestUnitPriceEur!)}` : 'No quote yet', rule: r.awardRuleLabel, chosenText: r.awardedTo ?? '—', status: r.statusLabel,
      canSend: r.status === 'draft', canCompare: r.status === 'open' && r.quotes.length > 1,
    }))).toEqual(G.procurement.rfqRows.map((r: any) => ({ ...r, due: day(r.due) })));
    expect([[rfqs.filter((r) => r.status !== 'awarded').length, `${rfqs.filter((r) => r.status === 'comparing').length} ready to award`], [rfqs.reduce((a, r) => a + r.quotes.length, 0), 'Across open requests']])
      .toEqual(kv(G.procurement.rfqKpis).slice(0, 2));
    for (const r of rfqs) {
      for (const [role, g] of Object.entries(G.procurement.rfqDrawers[r.number] as Record<string, any>)) {
        const can = await canAwardRfqs(PERSONA[role]);
        expect(r.quotes.map((q) => ({
          sup: q.supplier, price: $(q.unitPriceEur), total: $(q.totalEur!), lead: `${q.leadWeeks} wks`, terms: q.paymentTerms, grade: q.grade, score: `${q.score}/100`, isBest: q.isBest, isFast: q.isFastest,
          chosen: q.awarded, canAward: r.status === 'comparing' && !r.awardedTo && can, delta: q.isBest ? '—' : `+${$(q.deltaEur)}`,
        }))).toEqual(g.quotes);
        expect(g.meta.map((m: any) => m.v)).toEqual([`${r.partRef}${r.partName ? ' · ' + r.partName : ''}`, n(r.quantity!), g.meta[2].v, r.owner, r.awardRuleLabel, r.lastPriceEur != null ? $(r.lastPriceEur) : '—']);
        expect(g.hint).toBe(r.status === 'comparing' && !can ? 'Switch to Project manager or Procurement to award.' : r.status === 'awarded' ? `Awarded to ${r.awardedTo} — purchase order created as draft.` : '');
      }
    }
  });

  it('invoice rows, KPI inputs and drawers reproduce invRows / invKpis / invVals (3-way match)', async () => {
    const inv = await listSupplierInvoices();
    const dot = (s: string) => (s === 'ok' ? 'var(--color-accent)' : s === 'none' ? 'var(--color-neutral-100)' : s === 'partial' || s === 'diff' ? 'var(--color-accent-700)' : 'var(--color-neutral-700)');
    expect(inv.map((i) => ({
      id: i.number, supplier: i.supplier, poText: i.poNumber ?? '—', grText: i.receiptNumber ?? '—', amountText: $(i.amountEur), gapText: i.gapEur ? $(i.gapEur) : '—',
      date: day(fmtDOfIso(i.invoiceDate)), dueDate: day(fmtDOfIso(i.dueDate)), status: i.statusLabel, canApprove: i.canApprove, canPartial: i.canApprovePart, m: [dot(i.match.po), dot(i.match.gr), dot('ok')],
    }))).toEqual(G.procurement.invRows.map((r: any) => ({ ...r, date: day(r.date), dueDate: day(r.dueDate) })));
    const open = inv.filter((i) => i.status !== 'paid');
    expect([[open.length, $(open.reduce((a, i) => a + i.amountEur, 0))], [inv.filter((i) => i.status === 'blocked' || i.status === 'no_po').length, 'Quantity or PO mismatch'],
      [inv.filter((i) => i.status === 'awaiting_receipt').length, 'Invoice before delivery'], [inv.filter((i) => i.status === 'approved_for_payment').length, 'Pushed to X3 accounts payable']])
      .toEqual(kv(G.procurement.invKpis).slice(0, 4));
    expect(['Blocked', 'Awaiting receipt', 'No PO', 'Approved for payment', 'Paid'].map((s) => [s, inv.filter((i) => i.statusLabel === s).length])).toEqual(G.procurement.invChips.slice(1));
    for (const i of inv) {
      const g = G.procurement.invDrawers[i.number];
      expect([['Purchase order', i.poNumber ?? '—', $(i.poAmountEur), matchState.label(i.match.po)], ['Goods receipt', i.receiptNumber ?? '—', $(i.receiptAmountEur), matchState.label(i.match.gr)], ['Invoice', i.number, $(i.amountEur), 'Matched']])
        .toEqual(g.rows.map((x: any) => [x.k, x.ref, x.amt, x.state]));
      expect(g.meta.map((m: any) => m.v)).toEqual([g.meta[0].v, g.meta[1].v, i.paymentTerms, i.gapEur ? $(i.gapEur) : '—', i.blockingReason ?? '—']);
      expect(g.partialLabel).toBe(`Approve ${$(i.receiptAmountEur)} · request credit note`);
      expect(g.canReject).toBe(i.canReject);
    }
    expect(await countInvoicesToResolve()).toBe(3);
  });

  it('supplier scorecard reproduces supRows / supKpis (HLT-026 NCRs)', async () => {
    const sc = await getSupplierScorecard('HLT-026');
    expect(sc.rows.map((s) => ({ name: s.name, otd: `${s.onTimeDeliveryPct}%`, qual: `${s.qualityAcceptancePct}%`, ncr: `${s.ncrRatePct}%`, grade: s.grade, pos: s.openPoCount, ncrs: s.ncrsThisQuarter })))
      .toEqual(G.procurement.supRows);
    const r = sc.rows;
    expect([[r.length, `${r.filter((s) => s.grade === 'A').length} rated A`], [`${Math.round(r.reduce((a, s) => a + s.onTimeDeliveryPct, 0) / r.length)}%`, 'Weighted last 12 months'],
      [`${Math.round(r.reduce((a, s) => a + s.qualityAcceptancePct, 0) / r.length)}%`, 'Units accepted at receipt'], [r.filter((s) => s.grade === 'C').length, 'Improvement plan required'], [sc.supplierNcrs, 'This quarter']])
      .toEqual(kv(G.procurement.supKpis));
  });
});

// ── My approvals ───────────────────────────────────────────────────────────────────────────────────────

describe('My approvals — database-backed supply-chain and ECO kinds (08 §7.5)', () => {
  it.each(['director', 'pm', 'depthead', 'englead', 'quality', 'procurement', 'client'])('%s: PO, ECO, delivery QC, RFQ award and invoice items reproduce apprItems', async (role) => {
    const name = PERSONA[role];
    const items: { kind: string; id: string; title: string; sub: string; when: string; who: string }[] = [];
    if (role === 'pm' || role === 'director')
      for (const o of await poApprovalQueue('HLT-026', name)) items.push({ kind: 'Purchase order', id: o.number, title: `${o.supplier} · ${f(o.valueEur / 1000)}`, sub: o.refs.join(', '), when: day(fmtDOfIso(o.orderedOn!)), who: o.submittedBy ?? '' });
    for (const e of await ecoApprovalQueue({ name, role })) items.push({ kind: 'ECO', id: e.number, title: e.title, sub: `${e.typeLabel} · ${e.projectNames.join(', ')}`, when: day(fmtDOfIso(e.raisedOn)), who: e.requestedBy });
    if (role === 'quality' || role === 'procurement')
      for (const r of await qcQueue('HLT-026')) items.push({ kind: 'Delivery — quality check', id: r.number, title: `${r.supplier} · ${r.lines.map((l) => l.ref).join(', ')}`, sub: r.qc.remarks ?? '', when: day(fmtDOfIso(r.date!)), who: r.receivedBy ?? '' });
    if (role === 'pm' || role === 'procurement')
      for (const r of await rfqAwardQueue()) items.push({ kind: 'RFQ award', id: r.number, title: r.title, sub: `${r.quotes.length} quotes · ${r.awardRuleLabel}`, when: day(fmtDOfIso(r.replyDueOn)), who: r.owner });
    if (role === 'procurement' || role === 'director')
      for (const i of await invoiceQueue()) items.push({ kind: 'Invoice — 3-way match', id: i.number, title: `${i.supplier} · ${$(i.amountEur)}`, sub: i.status === 'no_po' ? 'No purchase order referenced' : 'Receipt does not cover invoice', when: day(fmtDOfIso(i.invoiceDate)), who: 'Accounts payable' });
    const kinds = new Set(['Purchase order', 'ECO', 'Delivery — quality check', 'RFQ award', 'Invoice — 3-way match']);
    const order = ['Purchase order', 'ECO', 'Delivery — quality check', 'RFQ award', 'Invoice — 3-way match'];
    expect(items.sort((a, b) => order.indexOf(a.kind) - order.indexOf(b.kind))).toEqual(
      G.myapprovals[role].items.filter((i: any) => kinds.has(i.kind)).map((i: any) => ({ ...i, when: day(i.when) })),
    );
  });

  it('the director holds no ECO approval key; a PM only gets the ECOs of the projects they manage', async () => {
    expect(await ecoApprovalQueue({ name: 'Marie Lefebvre', role: 'director' })).toEqual([]);
    expect(await ecoApprovalQueue({ name: 'S. Perrin', role: 'pm' })).toEqual([]);
    expect(ECO_APPROVER_KEYS).toEqual(['englead', 'quality', 'pm']);
  });
});
